-- AD25 CHECK (phase 1m, card B13 step Z4a): every row must be true
select 'inbox and ledger exist with forced RLS' as what, (select bool_and(c.relrowsecurity and c.relforcerowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='cp' and c.relname in ('consent_inbox','consent_ledger')) and (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='cp' and c.relname in ('consent_inbox','consent_ledger'))=2 as ok
union all select 'no table right for cp_lookup, cp_consent_customer or PUBLIC', not has_table_privilege('cp_lookup','cp.consent_inbox','select') and not has_table_privilege('cp_consent_customer','cp.consent_inbox','select') and not has_table_privilege('public','cp.consent_ledger','select')
union all select 'every consent function is SECURITY DEFINER with fixed search_path', (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='cp' and p.proname in ('consent_push','consent_cancel','consent_poll','consent_inbox_for','consent_decide','consent_revoke','consent_ledger_verify','consent_note','consent_is_approver','consent_approver_reach') and p.prosecdef and p.proconfig::text like '%search_path=pg_catalog, pg_temp%')=10
union all select 'PUBLIC can execute none of the doors', not has_function_privilege('public','cp.consent_push(uuid,text,text,text,text)','execute') and not has_function_privilege('public','cp.consent_decide(uuid,uuid,text,text)','execute') and not has_function_privilege('public','cp.consent_poll(uuid[])','execute')
union all select 'cp_lookup (the Control Plane) can push, cancel, poll', has_function_privilege('cp_lookup','cp.consent_push(uuid,text,text,text,text)','execute') and has_function_privilege('cp_lookup','cp.consent_cancel(uuid)','execute') and has_function_privilege('cp_lookup','cp.consent_poll(uuid[])','execute')
union all select 'cp_lookup can NEVER decide, revoke or read the customer inbox', not has_function_privilege('cp_lookup','cp.consent_decide(uuid,uuid,text,text)','execute') and not has_function_privilege('cp_lookup','cp.consent_revoke(uuid,uuid,text)','execute') and not has_function_privilege('cp_lookup','cp.consent_inbox_for(uuid,uuid)','execute')
union all select 'the customer role can decide, revoke, read inbox but never push', has_function_privilege('cp_consent_customer','cp.consent_decide(uuid,uuid,text,text)','execute') and has_function_privilege('cp_consent_customer','cp.consent_revoke(uuid,uuid,text)','execute') and has_function_privilege('cp_consent_customer','cp.consent_inbox_for(uuid,uuid)','execute') and not has_function_privilege('cp_consent_customer','cp.consent_push(uuid,text,text,text,text)','execute')
union all select 'ledger and inbox have their guard triggers', (select count(*) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='cp' and c.relname in ('consent_ledger','consent_inbox') and not t.tgisinternal)=5
union all select 'the window CHECK holds the scope maximum (60/30/15)', cp.consent_minutes('metadata')=60 and cp.consent_minutes('headers')=30 and cp.consent_minutes('content')=15 and cp.consent_minutes('x') is null
union all select 'the ledger chain verifies', cp.consent_ledger_verify()
union all select 'earlier doors are untouched', to_regprocedure('cp.lookup(text)') is null or has_function_privilege('cp_lookup','cp.lookup(text)','execute')
union all select 'no content, name, e-mail or money column in the inbox', not exists (select 1 from information_schema.columns where table_schema='cp' and table_name='consent_inbox' and column_name ~* '(email|name|subject|body|amount|price|address)')
union all select 'the approver rule is the real membership query (not a test copy)', pg_get_functiondef('cp.consent_is_approver(uuid,uuid)'::regprocedure) like '%public.org_members%'
union all select 'FACT (not a pass/fail): companies and companies with a reachable owner/admin = '||cp.consent_approver_reach()::text, true;
